public static String applyRelativePath(String path,String relativePath){
    if(path==null) return null;
    if(relativePath==null) return path;
    boolean leadingSlash = path.startsWith("/");
    String[] baseParts = path.split("/");
    List<String> stack = new ArrayList<>();
    for(String part: baseParts){
        if(part.isEmpty()) continue;
        stack.add(part);
    }
    String[] relParts = relativePath.split("/");
    for(String part: relParts){
        if(part.isEmpty() || ".".equals(part)) continue;
        if("..".equals(part)){
            if(!stack.isEmpty()){
                stack.remove(stack.size()-1);
            }
        } else {
            stack.add(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    if(leadingSlash) sb.append("/");
    for(int i=0;i<stack.size();i++){
        if(i>0) sb.append("/");
        sb.append(stack.get(i));
    }
    return sb.toString();
}
